// Einmaliger Reset 2026-08-01: 6 Vorgaenge waren einzig wegen des Symbol-Drift-Guards
// (Sparschwein/Geldsack/Rathaus) blockiert (sharepicNeedStage='topic_error'), siehe
// qaVerdictJson.violations - bei allen 6 war guard_symbol_drift der EINZIGE Verstoss, keine
// weiteren Probleme (anchors_few_objects o.ae.). Der Guard wurde am selben Tag gelockert
// (sparschwein/geldsack/rathaus aus der Klischee-Liste entfernt, siehe ALLRIS_QA_Agent "Deter-
// ministische Regelpruefung" + 4 weitere Kopien) - diese 6 Zeilen wuerden bei einer erneuten
// Pruefung jetzt nicht mehr blockiert. Setzt NUR sharepicNeedStage/visualPromptStage/imageStage
// und die Fehler-/Retry-Felder zurueck, ruehrt contentStage NICHT an (5 von 6 haben bereits
// content_posted, das bleibt unangetastet). Absichtlich NICHT dabei: 2026/138, 2026/143,
// 2026/107, 2026/094 (zusaetzlich anchors_few_objects - eigenstaendiges Problem, durch die
// Lockerung nicht geloest) und 2025/464 (guard_sensitive_scene - ein anderer, nicht gelockerter
// Guard).
const TARGETS = [
  { vorgangKey: 'vol_10617', vorgangsnummer: '2026/121' },
  { vorgangKey: 'vol_10423', vorgangsnummer: '2026/032' },
  { vorgangKey: 'vol_10484', vorgangsnummer: '2026/064' },
  { vorgangKey: 'vol_10582', vorgangsnummer: '2026/099' },
  { vorgangKey: 'vol_10644', vorgangsnummer: '2026/139' },
  { vorgangKey: 'vol_10405', vorgangsnummer: '2026/022' }
];

if (!TARGETS.length) {
  throw new Error('[SharepicNeedStage-Reset] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    sharepicNeedStage: 'topic_ok',
    visualPromptStage: 'needs_prompt',
    imageStage: 'not_started',
    visualDecisionReason: 'Manueller Reset 2026-08-01: Symbol-Drift-Guard (Sparschwein/Geldsack/Rathaus) gelockert, einziger Blockierungsgrund entfaellt',
    contentErrorReason: '',
    last_error_code: '',
    last_error_message: '',
    last_error_stage: '',
    last_error_at: '',
    next_retry_at: '',
    retry_count: 0
  }
}));
